lz4            apt=liblz4-dev  dnf=lz4-devel  pacman=lz4  zypper=liblz4-devel  xbps=liblz4-devel  emerge=app-arch/lz4
libmpv         apt=libmpv-dev  dnf=mpv-devel  pacman=mpv  zypper=mpv-devel  xbps=mpv-devel  emerge=media-video/mpv
ffmpeg-libs    apt=libavcodec-dev,libavformat-dev,libavutil-dev,libswscale-dev  dnf=ffmpeg-free-devel  pacman=ffmpeg  zypper=libavcodec-devel,libavformat-devel,libavutil-devel,libswscale-devel  xbps=ffmpeg-devel  emerge=media-video/ffmpeg
